/* VERSION of the modelled cores (the 10-22-2026 register maps); the system registers have their own. */
#define HOST_CORE_VERSION  0x10222026u
#define HOST_CAPTURE_MAX   65536u
#define HOST_MAX_CORES     16u
#define HOST_MAX_WORDS     64u
#define HOST_CLS_WORDS     (RTLNET_CLS_WINDOW_BYTES / 4u)
/* Classifier model build parameters (CAPS): 16 + 16 entries, 2 rules, 4 policers, 2 lanes, 64 bytes. */
#define HOST_CLS_CAPS      (16u | (16u << 5) | (2u << 10) | (4u << 13) | (2u << 16) | (8u << 21))
#define HOST_CLS_LATENCY   (31u | (23u << 8))

static char      g_capture[HOST_CAPTURE_MAX];
static size_t    g_capture_len;
static int       g_echo = 1;
static uint32_t  g_leds;
static uint32_t  g_scratch;
static uint32_t  g_link_caps = ETHS_LINK_MASK;   /* LINK_CAPS the model reports */
static uint32_t  g_reg_acc;                   /* register accesses of the firmware (reads and writes, all windows) */
static uintptr_t g_core_base[HOST_MAX_CORES];
static uint32_t  g_core_id[HOST_MAX_CORES];
static uintptr_t g_word_addr[HOST_MAX_WORDS];
static uint32_t  g_word_val[HOST_MAX_WORDS];
static int       g_reloads;
static clock_t   g_t0;
static int       g_cls_on;                    /* the classifier model answers at RTLNET_PLAT_CLS_BASE */
static uint32_t  g_cls_mode;                  /* CTRL.MODE */
static uint32_t  g_cls_mem[HOST_CLS_WORDS];   /* every other register word as written */

/* Protocol wrapper CAPS / CPU_CAPS model. */
static int       g_wrap_on;
static uint32_t  g_wrap_cpu_caps;

/* Checksum offload register model. */
#define HOST_EV_MAX        256u
static int       g_txo_on;
static uint32_t  g_txo_caps;
static uint32_t  g_txo_ctrl;
static uint32_t  g_txo_stuck;
static uint32_t  g_txo_idle_after = 2u;
static uint32_t  g_txo_status_reads;
static uint32_t  g_txo_feat_mask;     /* CTRL bits 4:3 of the receive features the CAPS announce */
static uint32_t  g_txo_cfg[5];        /* ACK_TIMER, ACK_LIMIT, BAT_TIMER, BAT_FRAMES, BAT_BYTES */
static uint32_t  g_txo_feat_cnt[RTLNET_TXO_NUM_ACK_COUNTERS + RTLNET_TXO_NUM_BAT_COUNTERS];
static uint32_t  g_txo_cnt[RTLNET_TXO_NUM_TX_COUNTERS + RTLNET_TXO_NUM_RX_COUNTERS];
static host_event_t g_ev[HOST_EV_MAX];
static unsigned  g_ev_n;

/**
 * @brief Set the LINK_CAPS the system-register model reports.
 * @param caps ETHS_LINK_* bits.
 * @return None.
 */
void host_model_set_link_caps(uint32_t caps)
{
    g_link_caps = caps & ETHS_LINK_MASK;
}

/**
 * @brief Clear the console capture buffer.
 * @return None.
 */
void host_capture_clear(void)
{
    g_capture_len = 0;
    g_capture[0] = '\0';
}

/**
 * @brief Console text produced since the last host_capture_clear().
 * @return NUL-terminated capture (truncated at HOST_CAPTURE_MAX - 1).
 */
const char *host_capture_text(void)
{
    return g_capture;
}

/**
 * @brief Select whether console output is also written to stdout.
 * @param on 1 to echo, 0 for capture only.
 * @return None.
 */
void host_console_echo(int on)
{
    g_echo = on;
}

/**
 * @brief Mark a core present (ID register reads id) or absent (id 0).
 * @param base Window base address of the core.
 * @param id   Core ID code, 0 to remove.
 * @return None.
 */
void host_model_set_core(uintptr_t base, uint32_t id)
{
    if (base == RTLNET_PLAT_CLS_BASE) {
        g_cls_on = (id != 0u) ? 1 : 0;
        g_cls_mode = 0u;
        memset(g_cls_mem, 0, sizeof(g_cls_mem));
        return;
    }
    for (unsigned i = 0; i < HOST_MAX_CORES; i++) {
        if (g_core_base[i] == base || (id != 0u && g_core_base[i] == 0u)) {
            g_core_base[i] = (id != 0u) ? base : 0u;
            g_core_id[i]   = id;
            return;
        }
    }
}

/**
 * @brief Protocol wrapper model: CAPS bit 5 (CPU path present) and CPU_CAPS.
 * @param cpu_path 1 when the CPU path is built.
 * @param cpu_caps CPU_CAPS value (queue sizes and bits 16..18).
 * @return None.
 */
void host_model_set_wrapper(int cpu_path, uint32_t cpu_caps)
{
    g_wrap_on = 1;
    g_wrap_cpu_caps = cpu_path ? cpu_caps : 0u;
    if (!cpu_path) {
        g_wrap_on = 2;
    }
}

/**
 * @brief Checksum offload window model.
 * @param present 1 for a core answering its header, 0 for an absent core (reads 0).
 * @param caps    CAPS value.
 * @return None. CTRL and the counters restart from 0.
 */
void host_model_txo_set(int present, uint32_t caps)
{
    g_txo_on = present;
    g_txo_caps = caps;
    g_txo_ctrl = 0u;
    g_txo_stuck = 0u;
    g_txo_idle_after = 2u;
    g_txo_status_reads = 0u;
    memset(g_txo_cnt, 0, sizeof(g_txo_cnt));
    g_txo_feat_mask = (((caps & RTLNET_TXO_CAPS_ACK_COALESCE) != 0u) ? RTLNET_TXO_CTRL_ACK_COALESCE : 0u) |
                      (((caps & RTLNET_TXO_CAPS_RX_BATCH) != 0u) ? RTLNET_TXO_CTRL_RX_BATCH : 0u);
    memset(g_txo_cfg, 0, sizeof(g_txo_cfg));
    memset(g_txo_feat_cnt, 0, sizeof(g_txo_feat_cnt));
}

/**
 * @brief Value of one receive-feature counter of the model (index: ACK counters, then batch counters).
 * @param index 0..11.
 * @param value Value.
 * @return None.
 */
void host_model_txo_feat_counter(uint32_t index, uint32_t value)
{
    if (index < RTLNET_TXO_NUM_ACK_COUNTERS + RTLNET_TXO_NUM_BAT_COUNTERS) {
        g_txo_feat_cnt[index] = value;
    }
}

/**
 * @brief A configuration register of the receive features as the model holds it (0 ACK_TIMER .. 4 BAT_BYTES).
 * @param index 0..4.
 * @return Value.
 */
uint32_t host_model_txo_cfg(uint32_t index)
{
    return (index < 5u) ? g_txo_cfg[index] : 0u;
}

/**
 * @brief STATUS reads before TX_IDLE reads 1 (0xFFFFFFFF: never).
 * @param reads Count; the read counter restarts.
 * @return None.
 */
void host_model_txo_idle_after(uint32_t reads)
{
    g_txo_idle_after = reads;
    g_txo_status_reads = 0u;
}

/**
 * @brief CTRL bits that ignore writes (a read-back mismatch).
 * @param mask Bits.
 * @return None.
 */
void host_model_txo_stuck(uint32_t mask)
{
    g_txo_stuck = mask;
}

/**
 * @brief CTRL as the model holds it.
 * @return Value.
 */
uint32_t host_model_txo_ctrl(void)
{
    return g_txo_ctrl;
}

/**
 * @brief Set CTRL directly (hardware state the firmware finds at start-up).
 * @param ctrl Value.
 * @return None.
 */
void host_model_txo_set_ctrl(uint32_t ctrl)
{
    g_txo_ctrl = ctrl & (RTLNET_TXO_CTRL_MASK | g_txo_feat_mask);
}

/**
 * @brief Clear the event log.
 * @return None.
 */
void host_events_clear(void)
{
    g_ev_n = 0u;
}

/**
 * @brief Number of logged events.
 * @return Count.
 */
unsigned host_events_count(void)
{
    return g_ev_n;
}

/**
 * @brief One logged event.
 * @param index 0 is the oldest.
 * @return Pointer, NULL beyond the log.
 */
const host_event_t *host_event(unsigned index)
{
    return (index < g_ev_n) ? &g_ev[index] : NULL;
}

/**
 * @brief Append an event.
 * @param kind  HOST_EV_*.
 * @param value Event value.
 * @return None.
 */
static void host_event_add(int kind, uint32_t value)
{
    if (g_ev_n < HOST_EV_MAX) {
        g_ev[g_ev_n].kind = kind;
        g_ev[g_ev_n].value = value;
        g_ev_n++;
    }
}

/**
 * @brief Log a change of the lwIP checksum flags (called by the lwIP stub).
 * @param flags The flags set.
 * @return None.
 */
void host_event_flags(uint32_t flags)
{
    host_event_add(HOST_EV_FLAGS, flags);
}

/**
 * @brief Checksum offload model read.
 * @param off Offset in the 4 KiB window.
 * @return Register value.
 */
static uint32_t host_txo_read(uint32_t off)
{
    switch (off) {
    case RTLNET_TXO_REG_ID:      return RTLNET_TXO_ID_VALUE;
    case RTLNET_TXO_REG_VERSION: return RTLNET_TXO_VERSION_VALUE;
    case RTLNET_TXO_REG_CAPS:    return g_txo_caps;
    case RTLNET_TXO_REG_CTRL:    return g_txo_ctrl;
    case RTLNET_TXO_REG_CAPS2:   return (g_txo_feat_mask != 0u) ? (4u | (2056u << 8)) : 0u;
    case RTLNET_TXO_REG_ACK_TIMER:  return g_txo_cfg[0];
    case RTLNET_TXO_REG_ACK_LIMIT:  return g_txo_cfg[1];
    case RTLNET_TXO_REG_BAT_TIMER:  return g_txo_cfg[2];
    case RTLNET_TXO_REG_BAT_FRAMES: return g_txo_cfg[3];
    case RTLNET_TXO_REG_BAT_BYTES:  return g_txo_cfg[4];
    case RTLNET_TXO_REG_STATUS: {
        int idle = (g_txo_idle_after != 0xFFFFFFFFu && g_txo_status_reads >= g_txo_idle_after) ? 1 : 0;
        g_txo_status_reads++;
        host_event_add(HOST_EV_STATUS_READ, (uint32_t)idle);
        return (uint32_t)idle | RTLNET_TXO_STATUS_RX_IDLE |
               ((g_txo_feat_mask != 0u) ? (RTLNET_TXO_STATUS_ACK_IDLE | RTLNET_TXO_STATUS_BAT_IDLE) : 0u);
    }
    case RTLNET_TXO_REG_LATENCY: return 18u | (17u << 8);
    default:
        break;
    }
    for (uint32_t i = 0u; i < RTLNET_TXO_NUM_TX_COUNTERS; i++) {
        if (off == RTLNET_TXO_REG_CNT_TX(i)) {
            return g_txo_cnt[i];
        }
    }
    for (uint32_t i = 0u; i < RTLNET_TXO_NUM_RX_COUNTERS; i++) {
        if (off == RTLNET_TXO_REG_CNT_RX(i)) {
            return g_txo_cnt[RTLNET_TXO_NUM_TX_COUNTERS + i];
        }
    }
    for (uint32_t i = 0u; g_txo_feat_mask != 0u && i < RTLNET_TXO_NUM_ACK_COUNTERS; i++) {
        if (off == RTLNET_TXO_REG_CNT_ACK(i)) {
            return g_txo_feat_cnt[i];
        }
    }
    for (uint32_t i = 0u; g_txo_feat_mask != 0u && i < RTLNET_TXO_NUM_BAT_COUNTERS; i++) {
        if (off == RTLNET_TXO_REG_CNT_BAT(i)) {
            return g_txo_feat_cnt[RTLNET_TXO_NUM_ACK_COUNTERS + i];
        }
    }
    return 0u;
}

/**
 * @brief Checksum offload model write: CTRL (bits 2:0, stuck bits keep their value) and CNT_CLEAR.
 * @param off   Offset in the 4 KiB window.
 * @param value Value.
 * @return None.
 */
static void host_txo_write(uint32_t off, uint32_t value)
{
    if (off == RTLNET_TXO_REG_CTRL) {
        host_event_add(HOST_EV_CTRL_WRITE, value);
        g_txo_ctrl = (g_txo_ctrl & g_txo_stuck) | (value & (RTLNET_TXO_CTRL_MASK | g_txo_feat_mask) & ~g_txo_stuck);
    } else if (off >= RTLNET_TXO_REG_ACK_TIMER && off <= RTLNET_TXO_REG_BAT_BYTES && g_txo_feat_mask != 0u) {
        g_txo_cfg[(off - RTLNET_TXO_REG_ACK_TIMER) / 4u] = value;
    } else if (off == RTLNET_TXO_REG_CNT_CLEAR && (value & 1u) != 0u) {
        memset(g_txo_cnt, 0, sizeof(g_txo_cnt));
        memset(g_txo_feat_cnt, 0, sizeof(g_txo_feat_cnt));
    }
}

/**
 * @brief LEDS register of the model.
 * @return Bits [7:1] as last written.
 */
uint32_t host_model_leds(void)
{
    return g_leds;
}

/**
 * @brief Number of plat_reload() calls.
 * @return Count since start.
 */
int host_reload_count(void)
{
    return g_reloads;
}

/**
 * @brief Classifier model read: header, CTRL/STATUS from MODE, other words as
 *        written (counters and policer statistics are set by the harness).
 * @param off Offset in the 4 KiB window.
 * @return Register value.
 */
static uint32_t host_cls_read(uint32_t off)
{
    switch (off) {
    case RTLNET_CLS_REG_ID:      return RTLNET_CLS_ID_VALUE;
    case RTLNET_CLS_REG_VERSION: return RTLNET_CLS_VERSION_VALUE;
    case RTLNET_CLS_REG_CAPS:    return HOST_CLS_CAPS;
    case RTLNET_CLS_REG_CTRL:    return g_cls_mode;
    case RTLNET_CLS_REG_STATUS:  return g_cls_mode << RTLNET_CLS_STATUS_MODE_SHIFT;
    case RTLNET_CLS_REG_LATENCY: return HOST_CLS_LATENCY;
    default:                     return g_cls_mem[(off / 4u) % HOST_CLS_WORDS];
    }
}

/**
 * @brief Classifier model write: MODE, CLEAR_TABLES (everything back to the
 *        power-up state) and plain storage for the other words.
 * @param off   Offset in the 4 KiB window.
 * @param value Value.
 * @return None.
 */
static void host_cls_write(uint32_t off, uint32_t value)
{
    if (off == RTLNET_CLS_REG_CTRL) {
        if ((value & RTLNET_CLS_CTRL_CLEAR_TABLES) != 0u) {
            memset(g_cls_mem, 0, sizeof(g_cls_mem));
            g_cls_mode = 0u;
        } else {
            g_cls_mode = value & RTLNET_CLS_CTRL_MODE_MASK;
        }
    } else if (off >= RTLNET_CLS_REG_TABLE_MODE(0u)) {
        g_cls_mem[(off / 4u) % HOST_CLS_WORDS] = value;
    }
}

/**
 * @brief Classifier model word as the harness sees it (also CTRL and STATUS).
 * @param offset Offset in the 4 KiB window.
 * @return Register value.
 */
uint32_t host_model_cls_peek(uint32_t offset)
{
    return host_cls_read(offset);
}

/**
 * @brief Set a classifier model word directly (counters, policer statistics).
 * @param offset Offset in the 4 KiB window.
 * @param value  Value.
 * @return None.
 */
void host_model_cls_poke(uint32_t offset, uint32_t value)
{
    g_cls_mem[(offset / 4u) % HOST_CLS_WORDS] = value;
}

/**
 * @brief Model of the board system-register read mux.
 * @param off Register offset.
 * @return Register value (fixed values, a running uptime, the RW registers).
 */
static uint32_t host_sysreg_read(uint32_t off)
{
    switch (off) {
    case ETHS_SYS_ID:          return ETHS_SYS_ID_VALUE;
    case ETHS_SYS_VERSION:     return ETHS_SYS_VERSION_VALUE;
    case ETHS_SYS_CAPS:        return (5u << ETHS_CAPS_NUM_BTN_SHIFT) | (8u << ETHS_CAPS_NUM_SW_SHIFT) |
                                      (8u << ETHS_CAPS_NUM_LEDS_SHIFT);
    case ETHS_SYS_BUILD_ID:    return 0x1234ABCDu;
    case ETHS_SYS_BUILD_DIRTY: return 0u;
    case ETHS_SYS_BOARD_ID:    return 0x54455354u;   /* "TEST" */
    case ETHS_SYS_CPU_CLK_HZ:  return RTLNET_PLAT_CPU_CLK_HZ;
    case ETHS_SYS_LINK_CAPS:   return g_link_caps;
    case ETHS_SYS_UPTIME_MS:   return plat_uptime_ms();
    case ETHS_SYS_LEDS:        return g_leds & 0xFEu;
    case ETHS_SYS_SWITCHES:    return 0xA5u;
    case ETHS_SYS_BUTTONS:     return 0x01u;
    case ETHS_SYS_SCRATCH:     return g_scratch;
    case ETHS_SYS_CLK_STATUS:  return ETHS_CLK_LOCKED;
    case ETHS_SYS_PHY_STATUS:  return ETHS_PHY_INT_N | ETHS_PHY_RST_N | ETHS_PHY_MDIO_IN;
    case ETHS_SYS_NET_STATUS:  return 0u;
    default:                   return 0u;
    }
}

/**
 * @brief rtlnet_mmio.h host hook: 32-bit read.
 * @param addr Byte address.
 * @return Model value: system registers, present-core headers, stored words,
 *         else 0 (an absent core's window).
 */
uint32_t rtlnet_host_reg_read32(uintptr_t addr)
{
    g_reg_acc++;
    if (g_cls_on && addr >= RTLNET_PLAT_CLS_BASE && addr < RTLNET_PLAT_CLS_BASE + RTLNET_CLS_WINDOW_BYTES) {
        return host_cls_read((uint32_t)(addr - RTLNET_PLAT_CLS_BASE));
    }
    if (g_txo_on && addr >= RTLNET_PLAT_TXO_BASE && addr < RTLNET_PLAT_TXO_BASE + RTLNET_TXO_WINDOW_BYTES) {
        return host_txo_read((uint32_t)(addr - RTLNET_PLAT_TXO_BASE));
    }
    if (g_wrap_on == 1 && addr == RTLNET_PLAT_PROT_BASE + 0x008u) {
        return 0x00000020u;                    /* CAPS: CPU_PATH_PRESENT */
    }
    if (g_wrap_on == 1 && addr == RTLNET_PLAT_PROT_BASE + 0x034u) {
        return g_wrap_cpu_caps;
    }
    if (addr >= RTLNET_PLAT_SYS_BASE && addr < RTLNET_PLAT_SYS_BASE + 0x1000u) {
        return host_sysreg_read((uint32_t)(addr - RTLNET_PLAT_SYS_BASE));
    }
    for (unsigned i = 0; i < HOST_MAX_CORES; i++) {
        if (g_core_id[i] != 0u && addr >= g_core_base[i] && addr < g_core_base[i] + 0x10u) {
            switch ((uint32_t)(addr - g_core_base[i])) {
            case RTLNET_REG_ID:      return g_core_id[i];
            case RTLNET_REG_VERSION: return HOST_CORE_VERSION;
            default:                 return 0u;
            }
        }
    }
    for (unsigned i = 0; i < HOST_MAX_WORDS; i++) {
        if (g_word_addr[i] == addr && addr != 0u) {
            return g_word_val[i];
        }
    }
    return 0u;
}

/**
 * @brief rtlnet_mmio.h host hook: 32-bit write.
 * @param addr  Byte address.
 * @param value Value.
 * @return None. LEDS and SCRATCH are modelled; other system offsets ignore
 *         writes; core windows ignore writes; any other address is stored.
 */
void rtlnet_host_reg_write32(uintptr_t addr, uint32_t value)
{
    g_reg_acc++;
    if (g_cls_on && addr >= RTLNET_PLAT_CLS_BASE && addr < RTLNET_PLAT_CLS_BASE + RTLNET_CLS_WINDOW_BYTES) {
        host_cls_write((uint32_t)(addr - RTLNET_PLAT_CLS_BASE), value);
        return;
    }
    if (g_txo_on && addr >= RTLNET_PLAT_TXO_BASE && addr < RTLNET_PLAT_TXO_BASE + RTLNET_TXO_WINDOW_BYTES) {
        host_txo_write((uint32_t)(addr - RTLNET_PLAT_TXO_BASE), value);
        return;
    }
    if (addr >= RTLNET_PLAT_SYS_BASE && addr < RTLNET_PLAT_SYS_BASE + 0x1000u) {
        uint32_t off = (uint32_t)(addr - RTLNET_PLAT_SYS_BASE);
        if (off == ETHS_SYS_LEDS) {
            g_leds = value & 0xFEu;
        } else if (off == ETHS_SYS_SCRATCH) {
            g_scratch = value;
        }
        return;
    }
    if (addr >= RTLNET_PLAT_WINDOW_BASE && addr < RTLNET_PLAT_WINDOW_BASE + RTLNET_CPU_RTLNET_SIZE) {
        return;
    }
    for (unsigned i = 0; i < HOST_MAX_WORDS; i++) {
        if (g_word_addr[i] == addr || g_word_addr[i] == 0u) {
            g_word_addr[i] = addr;
            g_word_val[i]  = value;
            return;
        }
    }
}

/**
 * @brief MDIO driver host hook (rtlnet_mdio.c under RTLNET_HOST_TEST): the
 *        MDC half-period spin takes no time in the model.
 * @param loops Spin count requested by the driver.
 * @return None.
 */
void rtlnet_host_spin(uint32_t loops);
void rtlnet_host_spin(uint32_t loops)
{
    (void)loops;
}

/* Interrupt controller model: handlers per INTC input, the enable mask, the input lines the models drive, and the CPU interrupt mask (a critical
 * section, or a handler running). A handler is called when its input is enabled, its line is high and the CPU interrupts are not masked: from
 * host_irq_deliver (called when a model changes a line, and when plat_irq_restore unmasks), so the code under test sees the interrupt between
 * any two register accesses, never inside a critical section. */
static void   (*g_irq_handler[RTLNET_CPU_IRQ_COUNT])(void *);
static void    *g_irq_ref[RTLNET_CPU_IRQ_COUNT];
static uint32_t g_irq_enabled;
static uint32_t g_irq_lines;
static int      g_irq_masked;
static int      g_irq_in_deliver;
static uint32_t g_irq_delivered;
static uint32_t g_irq_acc_total;      /* register accesses made inside handler calls */
static uint32_t g_irq_acc_max;        /* the most in one handler call */

/**
 * @brief Mask the CPU interrupts (nesting safe).
 * @return 8 when they were unmasked (the RISC-V mstatus.MIE bit), 0 when already masked; for plat_irq_restore.
 */
uint32_t plat_irq_save(void)
{
    uint32_t prev = g_irq_masked ? 0u : 8u;
    g_irq_masked = 1;
    return prev;
}

/**
 * @brief Return to the state plat_irq_save found; unmasking delivers a pending interrupt.
 * @param state Value from plat_irq_save.
 * @return None.
 */
void plat_irq_restore(uint32_t state)
{
    if ((state & 8u) != 0u) {
        g_irq_masked = 0;
        host_irq_deliver();
    }
}

/**
 * @brief Connect a handler on an INTC input; the input stays masked.
 * @param input   INTC input.
 * @param handler Handler.
 * @param ref     Argument of the handler.
 * @return 0, or -1 for an input out of range.
 */
int plat_irq_attach(unsigned input, void (*handler)(void *), void *ref)
{
    if (input >= RTLNET_CPU_IRQ_COUNT || handler == NULL) {
        return -1;
    }
    g_irq_handler[input] = handler;
    g_irq_ref[input] = ref;
    return 0;
}

/**
 * @brief Unmask or mask an INTC input.
 * @param input INTC input.
 * @param on    1 unmask, 0 mask.
 * @return None.
 */
void plat_irq_enable(unsigned input, int on)
{
    if (input >= RTLNET_CPU_IRQ_COUNT) {
        return;
    }
    if (on != 0) {
        g_irq_enabled |= 1u << input;
        host_irq_deliver();
    } else {
        g_irq_enabled &= ~(1u << input);
    }
}

/**
 * @brief A model drives an input line.
 * @param input INTC input.
 * @param level 1 high, 0 low.
 * @return None.
 */
void host_irq_set_line(unsigned input, uint32_t level)
{
    if (input >= RTLNET_CPU_IRQ_COUNT) {
        return;
    }
    if (level != 0u) {
        g_irq_lines |= 1u << input;
    } else {
        g_irq_lines &= ~(1u << input);
    }
}

/**
 * @brief Call the handlers of the inputs that are high and enabled while the CPU interrupts are unmasked (level sensitive: a handler that leaves
 *        the line high is called again, at most 8 times per call).
 * @return None.
 */
void host_irq_deliver(void)
{
    if (g_irq_in_deliver) {
        return;
    }
    g_irq_in_deliver = 1;
    for (int n = 0; n < 8 && !g_irq_masked; n++) {
        unsigned in = RTLNET_CPU_IRQ_COUNT;
        for (unsigned i = 0; i < RTLNET_CPU_IRQ_COUNT; i++) {
            if (((g_irq_lines & g_irq_enabled) & (1u << i)) != 0u && g_irq_handler[i] != NULL) {
                in = i;
                break;
            }
        }
        if (in == RTLNET_CPU_IRQ_COUNT) {
            break;
        }
        g_irq_masked = 1;      /* the trap masks the CPU interrupts while the handler runs */
        g_irq_delivered++;
        {
            uint32_t a0 = g_reg_acc;
            g_irq_handler[in](g_irq_ref[in]);
            a0 = g_reg_acc - a0;
            g_irq_acc_total += a0;
            if (a0 > g_irq_acc_max) {
                g_irq_acc_max = a0;
            }
        }
        g_irq_masked = 0;
    }
    g_irq_in_deliver = 0;
}

/**
 * @brief Handler calls made so far.
 * @return Count.
 */
uint32_t host_irq_delivered(void)
{
    return g_irq_delivered;
}

/**
 * @brief Register accesses made inside interrupt handler calls.
 * @param calls Receives the handler calls.
 * @param total Receives the accesses summed over the calls.
 * @param max   Receives the most accesses in one call.
 * @return None.
 */
void host_irq_access_stats(uint32_t *calls, uint32_t *total, uint32_t *max)
{
    *calls = g_irq_delivered;
    *total = g_irq_acc_total;
    *max = g_irq_acc_max;
}

/**
 * @brief Platform start: time origin, LEDs cleared.
 * @return None.
 */
void plat_init(void)
{
    g_t0 = clock();
    g_leds = 0u;
    memset(g_irq_handler, 0, sizeof(g_irq_handler));
    memset(g_irq_ref, 0, sizeof(g_irq_ref));
    g_irq_enabled = 0u;
    g_irq_masked = 0;
}

/**
 * @brief Console output: capture (for the demo checks) and optionally stdout.
 * @param s Text.
 * @param n Characters.
 * @return None.
 */
void plat_console_write(const char *s, size_t n)
{
    size_t room = HOST_CAPTURE_MAX - 1u - g_capture_len;
    size_t k = (n < room) ? n : room;
    memcpy(&g_capture[g_capture_len], s, k);
    g_capture_len += k;
    g_capture[g_capture_len] = '\0';
    if (g_echo) {
        (void)fwrite(s, 1u, n, stdout);
        (void)fflush(stdout);
    }
}

/**
 * @brief Console input is fed by host/main.c directly; never ready here.
 * @return -1.
 */
int plat_console_getc(void)
{
    return -1;
}

/**
 * @brief Console transmit counters: the harness writes straight to stdout, so all are zero.
 * @param out Receives the counters.
 */
void plat_console_tx_stats(plat_console_tx_t *out)
{
    out->ring_bytes = 0u;
    out->high_water = 0u;
    out->irqs = 0u;
    out->refills = 0u;
    out->drops = 0u;
    out->irq_mode = 0u;
}

/**
 * @brief Milliseconds since plat_init (processor time of the harness).
 * @return Elapsed milliseconds.
 */
uint32_t plat_uptime_ms(void)
{
    return (uint32_t)(((uint64_t)(clock() - g_t0) * 1000u) / (uint64_t)CLOCKS_PER_SEC);
}

/**
 * @brief Free-running tick of the host model (microseconds of processor time
 *        times RTLNET_PLAT_TICKS_PER_US).
 * @return Tick count.
 */
uint32_t plat_ticks(void)
{
    return (uint32_t)(((uint64_t)(clock() - g_t0) * 1000000u / (uint64_t)CLOCKS_PER_SEC) * RTLNET_PLAT_TICKS_PER_US);
}

/**
 * @brief Delay (no-op on the host: nothing waits on hardware).
 * @param us Microseconds.
 * @return None.
 */
void plat_delay_us(uint32_t us)
{
    (void)us;
}

/**
 * @brief Delay (no-op on the host).
 * @param ms Milliseconds.
 * @return None.
 */
void plat_delay_ms(uint32_t ms)
{
    (void)ms;
}

/**
 * @brief Periodic work (none on the host).
 * @return None.
 */
void plat_poll(void)
{
}

/**
 * @brief LED control into the model's LEDS register (index 1..7).
 * @param index LED number.
 * @param on    1 on, 0 off.
 * @return None.
 */
void plat_led_set(unsigned index, int on)
{
    if (index >= 1u && index <= 7u) {
        uint32_t mask = 1u << index;
        g_leds = on ? (g_leds | mask) : (g_leds & ~mask);
    }
}

/**
 * @brief LED shadow.
 * @return Bits [7:1].
 */
uint32_t plat_led_state(void)
{
    return g_leds;
}

/**
 * @brief Soft restart model: count it and restart the console (banner,
 *        defaults, user exec mode), as the target does after the jump to 0.
 * @return None.
 */
void plat_reload(void)
{
    g_reloads++;
    plat_init();
    cli_start();
}
